use verus::prelude::*;

verus! {

    /// Returns the lower‐bound insertion index `ret` into a nondecreasing array `a`
    /// such that
    ///   1. `ret <= a.len()`
    ///   2. for all `i < ret`, `a[i] < key`
    ///   3. for all `i` with `ret <= i < a.len()`, `a[i] ≥ key`
    ///
    /// In other words, it partitions `a` into values strictly less than `key`
    /// on the left, and values ≥ `key` on the right.
    pub fn binary_search(a: &[i32], key: i32) -> (ret: usize)
        // Precondition: `a` is sorted in nondecreasing order
        requires forall |i: usize, j: usize|  i < j && j < a.len() ==> a[i] <= a[j];
        // Postconditions describing the desired partition
        ensures ret <= a.len();
        ensures forall |i: usize|  i < ret ==> a[i] < key;
        ensures forall |i: usize|  ret <= i && i < a.len() ==> a[i] >= key;
    {
        let mut left: usize = 0;
        let mut right: usize = a.len();

        // Standard binary‐search loop, maintaining the invariants:
        // 1. 0 ≤ left ≤ right ≤ a.len()
        // 2. All indices < left are known < key
        // 3. All indices ≥ right are known ≥ key
        while left < right
            invariant 0 <= left && left <= right && right <= a.len();
            invariant forall |i: usize|  i < left            ==> a[i] < key;
            invariant forall |i: usize|  right <= i && i < a.len() ==> a[i] >= key;
            decreases right - left;
        {
            let mid = left + (right - left) / 2;
            if a[mid] < key {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        // When the loop exits, left == right is the desired insertion point
        left
    }

}